@import url("https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@300;400;500;700&display=swap");

#story-app {
--story-scrim: #0a0e16;
--story-bg-dim: 0.42;
--story-bg-blur: 6px;
--story-bg-fallback: linear-gradient(160deg, #1a2230 0%, #0b0f16 55%, #131a26 100%);
--story-text: #f2f7ff;
--story-narration-color: rgba(226, 238, 255, 0.86);
--story-text-shadow: 0 1px 8px rgba(4, 10, 22, 0.6);
--story-talk-gradient: linear-gradient(100deg, #eaf4ff 0%, #b6d6ff 45%, #7fb4ff 100%);
--story-font-size: 13.5px;
--story-line-height: 1.82;
--story-para-gap: 12px;
--story-user-bg: linear-gradient(150deg, rgba(150, 196, 255, 0.24), rgba(84, 128, 196, 0.16));
--story-user-text: #f4f9ff;
--story-user-border: rgba(186, 216, 255, 0.36);
--story-user-radius: 18px;
--story-user-max-w: 76%;
--story-think-bg: rgba(160, 198, 255, 0.08);
--story-think-border: rgba(178, 210, 255, 0.2);
--story-think-color: rgba(206, 226, 255, 0.66);
--story-os-border: rgba(176, 210, 255, 0.55);
--story-os-color: rgba(198, 220, 255, 0.72);
--story-os-bg: rgba(120, 170, 255, 0.07);
--story-avatar-size: 34px;
--story-avatar-radius: 12px;
--story-avatar-bg: linear-gradient(155deg, #b9d4f7, #6d8dba);
--story-topbar-color: #f3f8ff;
--story-topbar-dim: rgba(206, 226, 255, 0.66);
--story-topbar-bg: linear-gradient(180deg, rgba(22, 32, 48, 0.52), rgba(18, 26, 40, 0.18));
--story-topbar-blur: blur(18px) saturate(150%);
--story-topbar-border: rgba(180, 212, 255, 0.16);
--story-field-bg: rgba(18, 28, 44, 0.46);
--story-field-border: rgba(184, 216, 255, 0.42);
--story-field-radius: 18px;
--story-composer-bg: linear-gradient(180deg, rgba(12, 18, 28, 0), rgba(10, 16, 26, 0.62));
--story-bar-text: #eaf3ff;
--story-send-color: #ffffff;
--story-pop-bg: linear-gradient(165deg, rgba(32, 46, 66, 0.9), rgba(16, 24, 36, 0.92));
--story-pop-border: rgba(178, 212, 255, 0.22);
--story-pop-radius: 20px;
--story-pop-text: rgba(238, 246, 255, 0.95);
--story-pop-text-dim: rgba(196, 216, 240, 0.62);
--story-pop-chip-bg: rgba(160, 198, 255, 0.1);
--story-pop-chip-border: rgba(178, 212, 255, 0.16);
--story-pop-danger-bg: rgba(255, 108, 124, 0.16);
--story-menu-bg: linear-gradient(165deg, rgba(34, 48, 68, 0.92), rgba(18, 26, 40, 0.94));
--story-menu-border: rgba(178, 212, 255, 0.2);
--story-menu-text: rgba(236, 245, 255, 0.94);
--story-menu-hover: rgba(160, 200, 255, 0.14);
--story-menu-radius: 16px;
--story-tool-danger: #ff9ba8;
--story-switch-on: #7fb8ff;
--story-switch-off: rgba(180, 210, 245, 0.24);

font-family: "Noto Sans SC", "PingFang SC", -apple-system, "Helvetica Neue", sans-serif;
color: var(--story-text);
background: var(--story-bg-fallback);
letter-spacing: 0.01em;
-webkit-font-smoothing: antialiased;
}

.story-app::before {
content: "";
position: absolute;
inset: -3%;
background-image: var(--story-bg-image), var(--story-bg-fallback);
background-size: cover, cover;
background-position: center 22%, center;
background-repeat: no-repeat, no-repeat;
filter: blur(var(--story-bg-blur)) saturate(108%) brightness(0.98);
transform: scale(1.03);
opacity: 1;
pointer-events: none;
}

.story-app::after {
content: "";
position: absolute;
inset: 0;
background:
radial-gradient(120% 78% at 12% 0%, rgba(150, 200, 255, 0.14), transparent 62%),
radial-gradient(90% 60% at 92% 8%, rgba(180, 158, 255, 0.1), transparent 66%),
linear-gradient(180deg, rgba(8, 14, 24, calc(var(--story-bg-dim) * 0.7)) 0%, rgba(8, 13, 22, calc(var(--story-bg-dim) * 0.5)) 45%, rgba(6, 10, 18, var(--story-bg-dim)) 100%);
pointer-events: none;
}

header[data-app-bar] {
background: var(--story-topbar-bg);
-webkit-backdrop-filter: var(--story-topbar-blur);
backdrop-filter: var(--story-topbar-blur);
border-bottom: 1px solid var(--story-topbar-border);
box-shadow: 0 8px 28px -18px rgba(4, 10, 22, 0.9);
color: var(--story-topbar-color);
padding-top: 6px;
padding-bottom: 8px;
}

.story-topbar-name {
font-size: 16px;
font-weight: 500;
letter-spacing: 0.06em;
color: var(--story-topbar-color);
text-shadow: 0 1px 10px rgba(20, 44, 84, 0.55);
}

.story-topbar-note {
font-size: 11.5px;
font-weight: 300;
letter-spacing: 0.1em;
color: var(--story-topbar-dim);
margin-top: 2px;
}

.story-topbar-actions {
gap: 8px;
}

.story-icon-btn {
width: 32px;
height: 32px;
border-radius: 11px;
color: var(--story-topbar-color);
background: linear-gradient(160deg, rgba(168, 204, 255, 0.16), rgba(120, 160, 220, 0.06));
border: 1px solid rgba(184, 216, 255, 0.22);
box-shadow:
inset 0 1px 0 rgba(255, 255, 255, 0.22),
0 4px 14px -8px rgba(6, 14, 28, 0.9);
transition: transform 0.24s ease-out, background 0.24s ease-out, box-shadow 0.24s ease-out;
}

.story-icon-btn:active {
transform: scale(0.94);
background: linear-gradient(160deg, rgba(190, 220, 255, 0.28), rgba(130, 170, 230, 0.14));
box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.3);
}

.story-main {
padding-top: 10px;
padding-bottom: 18px;
}

.story-messages {
padding: 8px 16px 20px;
gap: 20px;
}

[data-role='char'],
[data-role='user'] {
gap: 10px;
}

[data-role='user'] {
flex-direction: row-reverse;
}

.story-msg-body {
gap: 8px;
animation: story-fade-rise 0.38s ease-out both;
}

[data-role='char'] .story-msg-body {
max-width: 88%;
}

.story-avatar {
width: var(--story-avatar-size);
height: var(--story-avatar-size);
border-radius: var(--story-avatar-radius);
background: var(--story-avatar-bg);
border: 1px solid rgba(206, 230, 255, 0.4);
box-shadow:
inset 0 1px 0 rgba(255, 255, 255, 0.4),
0 6px 16px -10px rgba(4, 12, 26, 0.9);
overflow: hidden;
flex-shrink: 0;
transition: transform 0.3s ease-out;
}

[data-role='char']:hover .story-avatar {
transform: scale(1.04);
}

.story-text {
font-size: var(--story-font-size);
line-height: var(--story-line-height);
font-weight: 400;
color: var(--story-text);
text-shadow: var(--story-text-shadow);
letter-spacing: 0.012em;
padding: 0 2px;
}

.story-text p,
.story-text > div {
margin-bottom: var(--story-para-gap);
}

.story-seg--narr {
color: var(--story-narration-color);
font-weight: 300;
font-size: calc(var(--story-font-size) - 0.5px);
letter-spacing: 0.03em;
padding: 2px 0 2px 10px;
border-left: 1px solid rgba(176, 210, 255, 0.28);
}

.story-seg--talk {
margin: 6px 0;
}

.story-talk-text {
font-size: calc(var(--story-font-size) + 1.2px);
font-weight: 500;
line-height: var(--story-line-height);
letter-spacing: 0.02em;
background-image: var(--story-talk-gradient);
-webkit-background-clip: text;
background-clip: text;
-webkit-text-fill-color: transparent;
color: transparent;
filter: drop-shadow(0 1px 5px rgba(12, 30, 60, 0.5));
}

.story-seg--os {
margin: 10px 0;
padding: 9px 14px;
border-radius: 14px 14px 14px 4px;
border: 1px dashed var(--story-os-border);
background: var(--story-os-bg);
-webkit-backdrop-filter: blur(8px);
backdrop-filter: blur(8px);
color: var(--story-os-color);
font-size: calc(var(--story-font-size) - 0.5px);
font-style: italic;
letter-spacing: 0.04em;
box-shadow: inset 0 1px 0 rgba(220, 236, 255, 0.12);
}

.story-bubble {
max-width: var(--story-user-max-w);
padding: 10px 15px;
border-radius: var(--story-user-radius);
background: var(--story-user-bg);
color: var(--story-user-text);
border: 1px solid var(--story-user-border);
-webkit-backdrop-filter: blur(14px) saturate(150%);
backdrop-filter: blur(14px) saturate(150%);
font-size: var(--story-font-size);
line-height: var(--story-line-height);
font-weight: 400;
letter-spacing: 0.015em;
box-shadow:
inset 0 1px 0 rgba(255, 255, 255, 0.28),
inset 0 -1px 0 rgba(120, 160, 220, 0.16),
0 10px 26px -16px rgba(4, 10, 22, 0.9);
transition: transform 0.26s ease-out, box-shadow 0.26s ease-out;
}

.story-bubble:active {
transform: scale(0.985);
}

.story-think {
margin: 8px 0;
border-radius: 14px;
background: var(--story-think-bg);
border: 1px solid var(--story-think-border);
-webkit-backdrop-filter: blur(10px);
backdrop-filter: blur(10px);
color: var(--story-think-color);
overflow: hidden;
box-shadow: inset 0 1px 0 rgba(220, 238, 255, 0.1);
transition: background 0.28s ease-out, border-color 0.28s ease-out;
}

.story-think-sum {
padding: 9px 13px;
font-size: 12px;
font-weight: 500;
letter-spacing: 0.08em;
color: var(--story-think-color);
border-bottom: 1px solid rgba(178, 210, 255, 0.12);
}

.story-think-body {
padding: 10px 13px 12px;
font-size: 12.5px;
line-height: 1.78;
font-weight: 300;
color: var(--story-think-color);
letter-spacing: 0.015em;
}

.story-msg-image {
border-radius: 16px;
border: 1px solid rgba(188, 218, 255, 0.28);
box-shadow:
inset 0 1px 0 rgba(255, 255, 255, 0.2),
0 12px 30px -18px rgba(4, 10, 22, 0.95);
overflow: hidden;
max-width: 100%;
transition: transform 0.3s ease-out;
}

.story-msg-image:active {
transform: scale(0.985);
}

.story-tools-btn {
width: 24px;
height: 24px;
border-radius: 9px;
color: rgba(206, 226, 255, 0.72);
background: rgba(150, 190, 245, 0.1);
border: 1px solid rgba(178, 212, 255, 0.16);
font-size: 12px;
transition: background 0.22s ease-out, transform 0.22s ease-out, color 0.22s ease-out;
}

.story-tools-btn:active {
transform: scale(0.92);
color: #f2f8ff;
background: rgba(170, 208, 255, 0.22);
}

.story-tools-menu {
background: var(--story-menu-bg);
border: 1px solid var(--story-menu-border);
border-radius: var(--story-menu-radius);
-webkit-backdrop-filter: blur(22px) saturate(160%);
backdrop-filter: blur(22px) saturate(160%);
color: var(--story-menu-text);
box-shadow:
inset 0 1px 0 rgba(226, 240, 255, 0.2),
0 18px 44px -22px rgba(2, 8, 18, 0.95);
overflow: hidden;
animation: story-pop-in 0.24s ease-out both;
}

.story-tools-layer {
font-size: 10.5px;
font-weight: 400;
letter-spacing: 0.12em;
color: rgba(186, 212, 244, 0.58);
padding: 7px 13px;
border-bottom: 1px solid rgba(178, 212, 255, 0.12);
background: rgba(150, 190, 245, 0.05);
}

.story-tools-item {
padding: 10px 13px;
font-size: 12.5px;
font-weight: 400;
letter-spacing: 0.02em;
color: var(--story-menu-text);
transition: background 0.2s ease-out, color 0.2s ease-out;
}

.story-tools-item:active {
background: var(--story-menu-hover);
}

.story-tools-item.is-danger {
color: var(--story-tool-danger);
}

.story-tools-item.is-danger:active {
background: rgba(255, 108, 124, 0.16);
}

.story-composer {
background: var(--story-composer-bg);
-webkit-backdrop-filter: blur(20px) saturate(150%);
backdrop-filter: blur(20px) saturate(150%);
border-top: 1px solid rgba(176, 210, 255, 0.14);
padding: 10px 14px calc(10px + env(safe-area-inset-bottom, 0px));
gap: 10px;
}

.story-plus-panel {
background: var(--story-pop-bg);
border: 1px solid var(--story-pop-border);
border-radius: var(--story-pop-radius);
-webkit-backdrop-filter: blur(22px) saturate(160%);
backdrop-filter: blur(22px) saturate(160%);
box-shadow:
inset 0 1px 0 rgba(226, 240, 255, 0.18),
0 16px 40px -24px rgba(2, 8, 18, 0.95);
padding: 12px;
gap: 10px;
animation: story-pop-in 0.26s ease-out both;
}

.story-plus-item {
border-radius: 16px;
background: var(--story-pop-chip-bg);
border: 1px solid var(--story-pop-chip-border);
color: var(--story-pop-text);
font-size: 12.5px;
font-weight: 400;
letter-spacing: 0.04em;
padding: 12px 8px;
transition: transform 0.22s ease-out, background 0.22s ease-out, border-color 0.22s ease-out;
}

.story-plus-item:active {
transform: scale(0.95);
background: rgba(170, 208, 255, 0.2);
border-color: rgba(196, 224, 255, 0.36);
}

.story-sheet-layer {
background: rgba(6, 12, 22, 0.5);
-webkit-backdrop-filter: blur(6px);
backdrop-filter: blur(6px);
animation: story-fade-in 0.26s ease-out both;
}

.story-sheet {
background: var(--story-pop-bg);
border: 1px solid var(--story-pop-border);
border-radius: var(--story-pop-radius) var(--story-pop-radius) 0 0;
-webkit-backdrop-filter: blur(26px) saturate(160%);
backdrop-filter: blur(26px) saturate(160%);
box-shadow:
inset 0 1px 0 rgba(230, 242, 255, 0.24),
0 -18px 50px -26px rgba(2, 8, 18, 0.95);
color: var(--story-pop-text);
padding: 18px 18px calc(18px + env(safe-area-inset-bottom, 0px));
animation: story-sheet-up 0.34s cubic-bezier(0.22, 0.9, 0.28, 1) both;
}

.story-pop {
background: var(--story-pop-bg);
border: 1px solid var(--story-pop-border);
border-radius: var(--story-pop-radius);
-webkit-backdrop-filter: blur(24px) saturate(160%);
backdrop-filter: blur(24px) saturate(160%);
box-shadow:
inset 0 1px 0 rgba(230, 242, 255, 0.22),
0 20px 48px -24px rgba(2, 8, 18, 0.95);
color: var(--story-pop-text);
animation: story-pop-in 0.24s ease-out both;
}

.story-sheet-title {
font-size: 14px;
font-weight: 500;
letter-spacing: 0.08em;
color: var(--story-pop-text);
padding-bottom: 12px;
margin-bottom: 4px;
border-bottom: 1px solid rgba(184, 214, 255, 0.14);
}

.story-sheet-item {
padding: 11px 14px;
border-radius: 13px;
background: var(--story-pop-chip-bg);
border: 1px solid var(--story-pop-chip-border);
color: var(--story-pop-text);
font-size: 12.5px;
font-weight: 400;
letter-spacing: 0.03em;
margin-bottom: 8px;
transition: transform 0.22s ease-out, background 0.22s ease-out, border-color 0.22s ease-out;
}

.story-sheet-item:active {
transform: scale(0.98);
background: rgba(170, 208, 255, 0.18);
border-color: rgba(196, 224, 255, 0.32);
}

.story-sheet-tab-list {
background: rgba(140, 180, 240, 0.1);
border: 1px solid rgba(178, 212, 255, 0.16);
border-radius: 999px;
padding: 3px;
gap: 3px;
box-shadow: inset 0 1px 4px rgba(6, 14, 26, 0.35);
}

.story-sheet-tab {
border-radius: 999px;
font-size: 12px;
font-weight: 400;
letter-spacing: 0.06em;
color: var(--story-pop-text-dim);
padding: 6px 14px;
transition: color 0.24s ease-out, background 0.24s ease-out, box-shadow 0.24s ease-out;
}

.story-sheet-tab.is-active {
color: #0f1a2c;
font-weight: 500;
background: linear-gradient(160deg, #e6f2ff, #b2d4ff);
box-shadow:
inset 0 1px 0 rgba(255, 255, 255, 0.9),
0 4px 12px -6px rgba(20, 60, 120, 0.6);
}

.story-sheet-slider-name {
font-size: 12px;
font-weight: 400;
letter-spacing: 0.05em;
color: var(--story-pop-text-dim);
}

.story-sheet-range {
accent-color: #8fc0ff;
height: 3px;
border-radius: 999px;
background: rgba(150, 190, 245, 0.24);
}

.story-sheet-range::-webkit-slider-thumb {
-webkit-appearance: none;
appearance: none;
width: 16px;
height: 16px;
border-radius: 50%;
background: linear-gradient(160deg, #f0f7ff, #a8ccff);
border: 1px solid rgba(255, 255, 255, 0.9);
box-shadow:
inset 0 1px 0 rgba(255, 255, 255, 0.9),
0 2px 8px rgba(10, 30, 60, 0.5);
}

.story-sheet-range::-moz-range-thumb {
width: 15px;
height: 15px;
border-radius: 50%;
background: linear-gradient(160deg, #f0f7ff, #a8ccff);
border: 1px solid rgba(255, 255, 255, 0.9);
box-shadow: 0 2px 8px rgba(10, 30, 60, 0.5);
}

.story-sheet-switch {
border-radius: 999px;
background: var(--story-switch-off);
box-shadow: inset 0 1px 3px rgba(6, 14, 26, 0.4);
transition: background 0.28s ease-out, box-shadow 0.28s ease-out;
}

.story-sheet-switch[data-on='true'],
.story-sheet-switch.is-on,
.story-sheet-switch.is-active {
background: linear-gradient(160deg, #a8d0ff, var(--story-switch-on));
box-shadow:
inset 0 1px 0 rgba(255, 255, 255, 0.5),
0 0 14px rgba(110, 170, 255, 0.5);
}

.story-sheet-divider {
height: 1px;
background: linear-gradient(90deg, transparent, rgba(184, 214, 255, 0.24), transparent);
margin: 12px 0;
border: none;
}

.story-model-bar {
background: rgba(16, 26, 42, 0.42);
border: 1px solid rgba(178, 212, 255, 0.16);
border-radius: 999px;
-webkit-backdrop-filter: blur(16px) saturate(150%);
backdrop-filter: blur(16px) saturate(150%);
padding: 5px 12px;
box-shadow:
inset 0 1px 0 rgba(224, 240, 255, 0.18),
0 6px 18px -12px rgba(4, 12, 26, 0.9);
transition: border-color 0.26s ease-out, background 0.26s ease-out;
}

.story-model-name {
font-size: 11.5px;
font-weight: 400;
letter-spacing: 0.07em;
color: rgba(206, 228, 255, 0.72);
}

.story-round-btn {
width: 34px;
height: 34px;
border-radius: 50%;
background: linear-gradient(160deg, rgba(168, 204, 255, 0.18), rgba(120, 160, 220, 0.08));
border: 1px solid rgba(184, 216, 255, 0.26);
color: var(--story-bar-text);
box-shadow:
inset 0 1px 0 rgba(255, 255, 255, 0.28),
0 4px 16px -10px rgba(4, 12, 26, 0.95);
transition: transform 0.24s ease-out, background 0.24s ease-out;
}

.story-round-btn:active {
transform: scale(0.92);
background: linear-gradient(160deg, rgba(190, 220, 255, 0.3), rgba(130, 170, 230, 0.16));
}

.story-input {
background: var(--story-field-bg);
border: 1px solid var(--story-field-border);
border-radius: var(--story-field-radius);
-webkit-backdrop-filter: blur(16px) saturate(150%);
backdrop-filter: blur(16px) saturate(150%);
color: #eef6ff;
font-family: inherit;
font-size: 13px;
line-height: 1.6;
letter-spacing: 0.015em;
padding: 10px 14px;
min-height: 40px;
box-shadow:
inset 0 1px 0 rgba(228, 242, 255, 0.24),
inset 0 -2px 10px rgba(6, 14, 26, 0.28),
0 6px 20px -14px rgba(4, 12, 26, 0.9);
transition: border-color 0.26s ease-out, box-shadow 0.26s ease-out, background 0.26s ease-out;
}

.story-input::placeholder {
color: rgba(190, 214, 242, 0.5);
font-weight: 300;
letter-spacing: 0.04em;
}

.story-input:focus {
border-color: rgba(186, 222, 255, 0.85);
background: rgba(22, 34, 52, 0.56);
box-shadow:
inset 0 1px 0 rgba(232, 244, 255, 0.34),
0 0 0 3px rgba(130, 180, 255, 0.16),
0 8px 24px -14px rgba(4, 12, 26, 0.95);
outline: none;
}

.story-send {
width: 40px;
height: 40px;
border-radius: 14px;
background: linear-gradient(155deg, #dcecff 0%, #a6ccff 42%, #6fa6ef 100%);
border: 1px solid rgba(230, 244, 255, 0.65);
color: var(--story-send-color);
box-shadow:
inset 0 1px 0 rgba(255, 255, 255, 0.9),
inset 0 -2px 6px rgba(40, 90, 160, 0.28),
0 8px 22px -12px rgba(60, 130, 230, 0.8);
transition: transform 0.24s ease-out, box-shadow 0.24s ease-out, filter 0.24s ease-out;
}

.story-send:active {
transform: scale(0.93);
filter: brightness(1.06);
box-shadow:
inset 0 1px 0 rgba(255, 255, 255, 0.95),
0 4px 14px -8px rgba(60, 130, 230, 0.9);
}

.story-send-icon {
color: #123a72;
filter: drop-shadow(0 1px 1px rgba(255, 255, 255, 0.6));
}

@keyframes story-fade-rise {
from {
opacity: 0;
transform: translateY(8px);
}
to {
opacity: 1;
transform: translateY(0);
}
}

@keyframes story-fade-in {
from { opacity: 0; }
to { opacity: 1; }
}

@keyframes story-pop-in {
from {
opacity: 0;
transform: translateY(-6px) scale(0.97);
}
to {
opacity: 1;
transform: translateY(0) scale(1);
}
}

@keyframes story-sheet-up {
from {
opacity: 0;
transform: translateY(26px);
}
to {
opacity: 1;
transform: translateY(0);
}
}

@media (prefers-reduced-motion: reduce) {
#story-app *,
.story-app::before,
.story-app::after {
animation-duration: 0.01ms !important;
animation-iteration-count: 1 !important;
transition-duration: 0.01ms !important;
}
}

@media (max-width: 360px) {
